// ---------- drag-drop layout sync (admin only) ----------
// body: { pool: [charId...], parties: [{ id, memberIds: [charId...] }] }
// organizers can move anyone; a player can join/leave a party with their own character
app.post('/api/assign', (req, res) => {
  const { placementId, partyId, subteam } = req.body || {};
  const pid = String(placementId || '');
  const c = findChar(pid.split('|')[0]);
  if (!c) return res.status(404).json({ error: 'Character not found' });
  if (!isOrganizer(req) && !ownsChar(req, c)) {
    return res.status(403).json({ error: 'No permission to organize' });
  }
  if (!partyId) { delete store.assignments[pid]; save(); broadcast(); return res.json({ ok: true }); }
  const party = findParty(partyId);
  if (!party) return res.status(404).json({ error: 'Party not found' });
  const t = subteam === 1 ? 1 : 0;
  let teamCount = 0; const pkey = String(c.playerName || '').trim().toLowerCase();
  for (const k of Object.keys(store.assignments)) {
    const a = store.assignments[k];
    if (!a || a.partyId !== partyId || k === pid) continue;
    if ((a.subteam === 1 ? 1 : 0) === t) teamCount++;
    const cc = findChar(k.split('|')[0]);
    if (cc && String(cc.playerName || '').trim().toLowerCase() === pkey) {
      return res.status(400).json({ error: `${c.playerName} is already in this party` });
    }
  }
  if (teamCount >= TEAM_SIZE) return res.status(400).json({ error: `This team is full (${TEAM_SIZE})` });
  let order = 0;
  for (const k of Object.keys(store.assignments)) { const a = store.assignments[k]; if (a && typeof a.slotOrder === 'number') order = Math.max(order, a.slotOrder); }
  store.assignments[pid] = { partyId, subteam: t, slotOrder: order + 1 };
  save(); broadcast();
  res.json({ ok: true });
});

app.post('/api/layout', requireOrganizer, (req, res) => {
  const { pool = [], parties = [] } = req.body || {};
  const charOf = (placementId) => findChar(String(placementId).split('|')[0]);
  for (const p of parties) {
    const teamA = p.teamA || [];
    const teamB = p.teamB || [];
    if (teamA.length > TEAM_SIZE || teamB.length > TEAM_SIZE) {
      return res.status(400).json({ error: `Each team holds at most ${TEAM_SIZE} players` });
    }
    const seen = new Set();
    for (const plid of [...teamA, ...teamB]) {
      const c = charOf(plid);
      if (!c) continue;
      const key = String(c.playerName || '').trim().toLowerCase();
      if (seen.has(key)) {
        return res.status(400).json({ error: `No duplicate player in one party: ${c.playerName}` });
      }
      seen.add(key);
    }
  }
  let order = 0;
  pool.forEach((plid) => { store.assignments[plid] = { partyId: null, slotOrder: order++ }; });
  for (const p of parties) {
    (p.teamA || []).forEach((plid) => { store.assignments[plid] = { partyId: p.id, subteam: 0, slotOrder: order++ }; });
    (p.teamB || []).forEach((plid) => { store.assignments[plid] = { partyId: p.id, subteam: 1, slotOrder: order++ }; });
  }
  save(); broadcast();
  res.json({ ok: true });
});

// ---------- AION2 official armory (proxy tw.ncsoft.com, public data) ----------
// NCSoft's own character-lookup API is public/unauthenticated but has no CORS
// headers for other origins, so we fetch it server-side and relay JSON.
const NC_BASE = 'https://tw.ncsoft.com';
// NCSoft's search endpoint ignores ?lang and always returns Chinese server
// names, unlike /character/info — so translate using a table built from
// /character/info?lang=en (which is authoritative) for every server id.
const NC_SERVER_NAME_EN = {
  1001: 'Siel', 1002: 'Nezekan', 1003: 'Vaizel', 1004: 'Kaisinel', 1005: 'Yustiel',
  1006: 'Ariel', 1007: 'Fregion', 1008: 'Meslamtaeda', 1009: 'Hithanya', 1010: 'Nania',
  1011: 'Tahavatha', 1012: 'Luteros', 1013: 'Phernos', 1014: 'Daminu', 1015: 'Kasaka',
  1016: 'Bakarma', 1017: 'Tsenka', 1018: 'Kochi',
  2001: 'Israphel', 2002: 'Zikel', 2003: 'Triniel', 2004: 'Lumiel', 2005: 'Marchutan',
  2006: 'Azphel', 2007: 'Ereshkigal', 2008: 'Beritra', 2009: 'Nemon', 2010: 'Hadala',
  2011: 'Ludra', 2012: 'Ulgorn', 2013: 'Munin', 2014: 'Odar', 2015: 'Zemurru',
  2016: 'Kromede', 2017: 'Quai', 2018: 'Baba',
};
const ncCache = new Map(); // key -> { at, data }
function ncCacheGet(key, ttlMs) {
  const hit = ncCache.get(key);
  if (hit && (Date.now() - hit.at) < ttlMs) return hit.data;
  return null;
}
function ncCacheSet(key, data) { ncCache.set(key, { at: Date.now(), data }); }
async function ncGet(pathAndQuery) {
  const res = await fetch(NC_BASE + pathAndQuery, {
    headers: {
      Accept: 'application/json',
      'User-Agent': 'Mozilla/5.0 (compatible; SanctuaryParty/1.0)',
      Referer: NC_BASE + '/aion2/characters/index',
    },
  });
  if (!res.ok) throw new Error('AION2 lookup failed (' + res.status + ')');
  return res.json();
}
// crude per-IP throttle so we don't hammer NCSoft's public API
const ncHits = new Map(); // ip -> [timestamps]
function ncRateLimited(ip) {
  const now2 = Date.now();
  const hits = (ncHits.get(ip) || []).filter((t) => now2 - t < 60000);
  hits.push(now2);
  ncHits.set(ip, hits);
  return hits.length > 30; // 30 req/min/IP
}
app.get('/api/aion2/search', async (req, res) => {
  if (ncRateLimited(req.ip || '')) return res.status(429).json({ error: 'Too many lookups, slow down' });
  const keyword = String(req.query.keyword || '').trim().slice(0, 40);
  if (!keyword) return res.json({ list: [] });
  const cacheKey = 'search:' + keyword.toLowerCase();
  const cached = ncCacheGet(cacheKey, 30000);
  if (cached) return res.json(cached);
  try {
    // NCSoft's "race" param is actually a faction filter (1=Elyos, 2=Asmodian) —
    // there is no "both" value, so query each faction and merge the results.
    const kw = encodeURIComponent(keyword);
    const [elyos, asmo] = await Promise.all([
      ncGet(`/aion2/api/search/character?keyword=${kw}&race=1&serverId=&page=1&size=20&lang=en`),
      ncGet(`/aion2/api/search/character?keyword=${kw}&race=2&serverId=&page=1&size=20&lang=en`),
    ]);
    const seen = new Set();
    const list = [...(elyos.list || []), ...(asmo.list || [])]
      .filter((c) => (seen.has(c.characterId) ? false : (seen.add(c.characterId), true)))
      .map((c) => ({
        characterId: c.characterId,
        name: String(c.name || '').replace(/<\/?strong>/g, ''),
        serverId: c.serverId,
        serverName: NC_SERVER_NAME_EN[c.serverId] || c.serverName,
        level: c.level,
        profileImageUrl: c.profileImageUrl && c.profileImageUrl.startsWith('http') ? c.profileImageUrl : 'https://profileimg.plaync.com' + (c.profileImageUrl || ''),
      }));
    const out = { list };
    ncCacheSet(cacheKey, out);
    res.json(out);
  } catch (e) { res.status(502).json({ error: e.message }); }
});
app.get('/api/aion2/character', async (req, res) => {
  if (ncRateLimited(req.ip || '')) return res.status(429).json({ error: 'Too many lookups, slow down' });
  const serverId = String(req.query.serverId || '').trim();
  const characterId = String(req.query.characterId || '').trim();
  if (!/^\d+$/.test(serverId) || !/^[A-Za-z0-9_%+=.-]+$/.test(characterId)) {
    return res.status(400).json({ error: 'Missing serverId/characterId' });
  }
  const cacheKey = 'char:' + serverId + ':' + characterId;
  const cached = ncCacheGet(cacheKey, 10 * 60000);
  if (cached) return res.json(cached);
  try {
    // characterId comes from NCSoft's own search results already percent-encoded
    // (e.g. "...jCA%3D") — pass it through as-is, do NOT re-encode it.
    const [info, gear] = await Promise.all([
      ncGet(`/aion2/api/character/info?lang=en&characterId=${characterId}&serverId=${serverId}`),
      ncGet(`/aion2/api/character/equipment?lang=en&characterId=${characterId}&serverId=${serverId}`),
    ]);
    const items = (gear.equipment && gear.equipment.equipmentList) || [];
    const detailed = await Promise.allSettled(items.map((it) =>
      ncGet(`/aion2/api/character/equipment/item?id=${it.id}&enchantLevel=${(it.enchantLevel || 0) + (it.exceedLevel || 0)}&characterId=${characterId}&serverId=${serverId}&slotPos=${it.slotPos}&lang=en`)
    ));
    const equipment = items.map((it, i) => {
      const d = detailed[i];
      return d.status === 'fulfilled' ? { ...it, ...d.value } : it;
    });
    const out = { profile: info.profile, stat: (info.stat && info.stat.statList) || [], equipment };
    ncCacheSet(cacheKey, out);
    res.json(out);
  } catch (e) { res.status(502).json({ error: e.message }); }
});

