// post/replace your own "looking for party" banner
app.post('/api/recruit-banner', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'Please log in with Discord first' });
  let { server, world, class: cls, cp } = req.body || {};
  server = server === 'Global' ? 'Global' : 'TW';
  world = String(world || '').trim().slice(0, 30);
  cls = String(cls || '').trim().slice(0, 40);
  cp = Math.max(0, parseInt(cp, 10) || 0);
  store.recruitBanners = store.recruitBanners.filter((b) => !(b.ownerId === u.discordId && b.server === server));
  store.recruitBanners.unshift({ id: rid(), ownerId: u.discordId, name: u.name, server, world, class: cls, cp, createdAt: now() });
  if (store.recruitBanners.length > 2000) store.recruitBanners.length = 2000;
  save(); res.json({ ok: true });
});
app.delete('/api/recruit-banner', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'unauthorized' });
  const server = req.query.server === 'Global' ? 'Global' : 'TW';
  store.recruitBanners = store.recruitBanners.filter((b) => !(b.ownerId === u.discordId && b.server === server));
  save(); res.json({ ok: true });
});
app.post('/api/recruits', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'Please log in with Discord before creating a party' });
  let { server, world, dungeon, note, startTime, class: cls, cp } = req.body || {};
  server = server === 'Global' ? 'Global' : 'TW';
  world = String(world || '').trim().slice(0, 30);
  dungeon = String(dungeon || '').trim().slice(0, 40);
  note = String(note || '').trim().slice(0, 300);
  cls = String(cls || '').trim().slice(0, 40);
  cp = Math.max(0, parseInt(cp, 10) || 0);
  if (!dungeon) return res.status(400).json({ error: 'Please specify a dungeon' });
  const r = {
    id: rid(), server, world, dungeon, note, startTime: startTime ? Number(startTime) : null,
    ownerId: u.discordId, ownerName: u.name, createdAt: now(), closed: false,
    members: [{ discordId: u.discordId, name: u.name, class: cls, cp, joinedAt: now() }],
  };
  store.recruits.unshift(r);
  if (store.recruits.length > 2000) store.recruits.length = 2000;
  logEvent(`Created recruit party ${dungeon} (${server})`, u.name);
  save(); res.json({ id: r.id });
});
app.post('/api/recruits/:id/join', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'Please log in with Discord before joining' });
  const r = store.recruits.find((x) => x.id === req.params.id);
  if (!r || r.closed) return res.status(404).json({ error: 'Party not found' });
  if (r.members.some((m) => m.discordId === u.discordId)) return res.status(400).json({ error: 'You are already in this party' });
  if (r.members.length >= RECRUIT_SIZE) return res.status(400).json({ error: 'Party is full' });
  let { class: cls, cp } = req.body || {};
  cls = String(cls || '').trim().slice(0, 40);
  cp = Math.max(0, parseInt(cp, 10) || 0);
  r.members.push({ discordId: u.discordId, name: u.name, class: cls, cp, joinedAt: now() });
  store.recruitBanners = store.recruitBanners.filter((b) => b.ownerId !== u.discordId || b.server !== r.server);
  save(); res.json({ ok: true });
});
app.post('/api/recruits/:id/leave', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'unauthorized' });
  const r = store.recruits.find((x) => x.id === req.params.id);
  if (!r) return res.status(404).json({ error: 'Party not found' });
  if (u.discordId === r.ownerId) return res.status(400).json({ error: 'Owner cannot leave; delete the party instead' });
  r.members = r.members.filter((m) => m.discordId !== u.discordId);
  save(); res.json({ ok: true });
});
app.post('/api/recruits/:id/kick', (req, res) => {
  const u = currentUser(req);
  const r = store.recruits.find((x) => x.id === req.params.id);
  if (!r) return res.status(404).json({ error: 'Party not found' });
  if (!(u && r.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'Party owner only' });
  const { discordId } = req.body || {};
  if (discordId === r.ownerId) return res.status(400).json({ error: 'Cannot kick the owner' });
  r.members = r.members.filter((m) => m.discordId !== discordId);
  save(); res.json({ ok: true });
});
app.put('/api/recruits/:id', (req, res) => {
  const u = currentUser(req);
  const r = store.recruits.find((x) => x.id === req.params.id);
  if (!r) return res.status(404).json({ error: 'Party not found' });
  if (!(u && r.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'You can only edit parties you created' });
  const b = req.body || {};
  if (b.dungeon !== undefined) { const d = String(b.dungeon || '').trim().slice(0, 40); if (d) r.dungeon = d; }
  if (b.world !== undefined) r.world = String(b.world || '').trim().slice(0, 30);
  if (b.note !== undefined) r.note = String(b.note || '').trim().slice(0, 300);
  if (b.startTime !== undefined) r.startTime = b.startTime ? Number(b.startTime) : null;
  if (b.closed !== undefined) r.closed = !!b.closed;
  save(); res.json({ ok: true });
});
app.delete('/api/recruits/:id', (req, res) => {
  const u = currentUser(req);
  const r = store.recruits.find((x) => x.id === req.params.id);
  if (!r) return res.status(404).json({ error: 'Party not found' });
  if (!(u && r.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'You can only delete parties you created' });
  store.recruits = store.recruits.filter((x) => x.id !== req.params.id);
  save(); res.json({ ok: true });
});

// ---------- Market (kina trading) ----------
// real-time notifications: poster subscribes; buyers can "ping" a listing
const marketSubs = new Map(); // discordId -> Set(res)
function pushMarketNotify(discordId, payload) {
  const set = marketSubs.get(discordId);
  if (!set || !set.size) return false;
  const data = `data: ${JSON.stringify(payload)}\n\n`;
  for (const res of set) { try { res.write(data); } catch {} }
  return true;
}
app.get('/api/market/notifications', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).end();
  res.set({ 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
  if (res.flushHeaders) res.flushHeaders();
  res.write(': connected\n\n');
  let set = marketSubs.get(u.discordId);
  if (!set) { set = new Set(); marketSubs.set(u.discordId, set); }
  set.add(res);
  const ka = setInterval(() => { try { res.write(': ka\n\n'); } catch {} }, 25000);
  req.on('close', () => { clearInterval(ka); set.delete(res); if (!set.size) marketSubs.delete(u.discordId); });
});

const marketPingLimit = new Map(); // ip|listingId -> ts
app.post('/api/market/:id/ping', (req, res) => {
  const m = store.market.find((x) => x.id === req.params.id);
  if (!m || m.closed) return res.status(404).json({ error: 'Listing not found' });
  const key = (req.ip || '') + '|' + m.id;
  const last = marketPingLimit.get(key) || 0;
  if (Date.now() - last < 30000) return res.status(429).json({ error: 'Just pinged recently, please wait' });
  marketPingLimit.set(key, Date.now());
  const u = currentUser(req);
  const online = pushMarketNotify(m.discordId, {
    type: 'ping', listingId: m.id, listingType: m.type, category: m.category || 'kina', title: m.title || '', price: m.price != null ? m.price : (m.rate || 0), server: m.server,
    fromName: u ? u.name : 'Someone interested', fromId: u ? u.discordId : null, at: Date.now(),
  });
  res.json({ ok: true, online });
});

app.get('/api/market', (req, res) => {
  const server = req.query.server === 'Global' ? 'Global' : 'TW';
  const listings = store.market
    .filter((m) => m.server === server)
    .map((m) => ({
      id: m.id, type: m.type, server: m.server, world: m.world || '', category: m.category || 'kina', title: m.title || '',
      price: m.price != null ? m.price : (m.rate || 0), amount: m.amount, note: m.note, image: m.image || '',
      ownerName: m.ownerName, discordId: m.discordId, createdAt: m.createdAt, closed: !!m.closed,
    }));
  res.json({ listings });
});

app.post('/api/market', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'Please log in with Discord before posting' });
  let { type, server, category, title, price, amount, note } = req.body || {};
  type = type === 'buy' ? 'buy' : 'sell';
  server = server === 'Global' ? 'Global' : 'TW';
  category = ['kina', 'item', 'account'].includes(category) ? category : 'kina';
  price = Math.max(0, Number(price) || 0);
  title = String(title || '').trim().slice(0, 80);
  amount = String(amount || '').trim().slice(0, 60);
  note = String(note || '').trim().slice(0, 300);
  let { image } = req.body || {};
  image = String(image || '').trim().slice(0, 500);
  if (image && !/^https?:\/\//i.test(image)) image = '';
  let { world } = req.body || {};
  world = String(world || '').trim().slice(0, 30);
  if (!price) return res.status(400).json({ error: 'Please enter a price' });
  if (category !== 'kina' && !title) return res.status(400).json({ error: 'Please enter item name / account spec' });
  const m = { id: rid(), type, server, world, category, title, price, amount, note, image, ownerId: u.discordId, ownerName: u.name, discordId: u.discordId, createdAt: now(), closed: false };
  store.market.unshift(m);
  if (store.market.length > 3000) store.market.length = 3000;
  const catTh = category === 'item' ? 'Item' : category === 'account' ? 'Account' : 'kina';
  logEvent(`PostMarket ${type === 'sell' ? 'Sell' : 'Buy'} ${catTh} (${server})`, u.name);
  save();
  res.json({ id: m.id });
});

app.put('/api/market/:id', (req, res) => {
  const m = store.market.find((x) => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'Listing not found' });
  const u = currentUser(req);
  if (!(u && m.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'You can only edit your own listing' });
  let { type, server, category, title, price, amount, note } = req.body || {};
  if (type !== undefined) m.type = type === 'buy' ? 'buy' : 'sell';
  if (server !== undefined) m.server = server === 'Global' ? 'Global' : 'TW';
  if (category !== undefined) m.category = ['kina', 'item', 'account'].includes(category) ? category : (m.category || 'kina');
  if (title !== undefined) m.title = String(title || '').trim().slice(0, 80);
  if (price !== undefined) { const pr = Math.max(0, Number(price) || 0); if (pr) m.price = pr; }
  if (amount !== undefined) m.amount = String(amount || '').trim().slice(0, 60);
  if (note !== undefined) m.note = String(note || '').trim().slice(0, 300);
  if (req.body && req.body.image !== undefined) { let img = String(req.body.image || '').trim().slice(0, 500); m.image = /^https?:\/\//i.test(img) ? img : ''; }
  if (req.body && req.body.world !== undefined) m.world = String(req.body.world || '').trim().slice(0, 30);
  save();
  res.json({ ok: true });
});

app.post('/api/market/:id/close', (req, res) => {
  const m = store.market.find((x) => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'not found' });
  const u = currentUser(req);
  if (!(u && m.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'You can only manage your own listing' });
  m.closed = !m.closed;
  save();
  res.json({ ok: true, closed: m.closed });
});

app.delete('/api/market/:id', (req, res) => {
  const m = store.market.find((x) => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'not found' });
  const u = currentUser(req);
  if (!(u && m.ownerId === u.discordId) && !isAdmin(req)) return res.status(403).json({ error: 'You can only delete your own listing' });
  store.market = store.market.filter((x) => x.id !== req.params.id);
  save();
  res.json({ ok: true });
});


// ---------- global chat (last 200 messages) ----------
const chatSubs = new Set();
let chatSaveTimer = null;
function scheduleChatSave() { if (chatSaveTimer) return; chatSaveTimer = setTimeout(() => { chatSaveTimer = null; save(); }, 4000); }
function chatBroadcast(msg) {
  const data = `data: ${JSON.stringify(msg)}\n\n`;
  for (const res of chatSubs) { try { res.write(data); } catch {} }
}
app.get('/api/chat', (_req, res) => { res.json({ messages: store.chat.slice(-200) }); });
app.get('/api/chat/names', (_req, res) => {
  const set = new Set();
  for (const m of store.chat) if (m.name) set.add(m.name);
  for (const c of store.characters) if (c.playerName) set.add(String(c.playerName).trim());
  for (const r of store.recruits) for (const mm of (r.members || [])) if (mm.name) set.add(mm.name);
  for (const sid of Object.keys(store.sessions)) { const u = store.sessions[sid]; if (u && u.name) set.add(u.name); }
  // group tags: all + party names + category names (spaces removed for tag)
  const groups = [{ tag: 'all', label: 'all', kind: 'all' }];
  for (const g of store.groups) groups.push({ tag: String(g.name).replace(/\s+/g,''), label: g.name, kind: 'category' });
  for (const p of store.parties) groups.push({ tag: String(p.name).replace(/\s+/g,''), label: p.name, kind: 'party' });
  res.json({ names: [...set].filter(Boolean).slice(0, 500), groups });
});
app.get('/api/chat/stream', (req, res) => {
  res.set({ 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
  if (res.flushHeaders) res.flushHeaders();
  res.write(': connected\n\n');
  chatSubs.add(res);
  const ka = setInterval(() => { try { res.write(': ka\n\n'); } catch {} }, 25000);
  req.on('close', () => { clearInterval(ka); chatSubs.delete(res); });
});
const chatRate = new Map(); // discordId -> ts
app.post('/api/chat', (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: 'Please log in with Discord to chat' });
  let text = String((req.body && req.body.text) || '').trim().slice(0, 300);
  if (!text) return res.status(400).json({ error: 'Empty message' });
  const last = chatRate.get(u.discordId) || 0;
  if (Date.now() - last < 800) return res.status(429).json({ error: 'Slow down a bit' });
  chatRate.set(u.discordId, Date.now());
  const msg = { id: rid(), name: u.name, discordId: u.discordId, text, at: Date.now(), admin: isDiscordAdmin(u.discordId) };
  store.chat.push(msg);
  if (store.chat.length > 200) store.chat = store.chat.slice(-200);
  chatBroadcast(msg);
  scheduleChatSave();
  res.json({ ok: true });
});
// admin can delete a chat message
app.delete('/api/chat/:id', requireAdmin, (req, res) => {
  store.chat = store.chat.filter((m) => m.id !== req.params.id);
  chatBroadcast({ deleted: req.params.id });
  scheduleChatSave();
  res.json({ ok: true });
});

